To solve this problem, we need to determine the number of beautiful submatrices in a given matrix. A submatrix is considered beautiful if every row and every column in the submatrix can be rearranged to form palindromic sequences. 

### Approach
1. **Prefix Sum Arrays**: Compute prefix sums for each row and column to efficiently calculate the sum of any submatrix.
2. **Check Palindrome Conditions**: For each possible submatrix, check if every row and every column can form a palindrome by ensuring each character's count is even (for even-length sequences) or the count is even except for one character (for odd-length sequences).
3. **Iterate Over All Submatrices**: Check all possible submatrices and count those that meet the palindrome conditions for both rows and columns.

### Solution Code
```cpp
#include <vector>
#include <string>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<char>> mat(n, vector<char>(m));
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            mat[i][j] = cin >> mat[i][j];
        }
    }

    // Precompute prefix sums for rows
    vector<vector<int>> prefix(n, vector<int>(m + 1, 0));
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            prefix[i][j + 1] = prefix[i][j] + (mat[i][j] - 'a' + 1);
        }
    }

    // Precompute prefix sums for columns
    vector<vector<int>> prefix_col(n + 1, vector<int>(m, 0));
    for(int j = 0; j < m; ++j) {
        for(int i = 0; i < n; ++i) {
            prefix_col[i + 1][j] = prefix_col[i][j] + (mat[i][j] - 'a' + 1);
        }
    }

    // Precompute 2D prefix sum
    vector<vector<int>> prefix(n, vector<int>(m, 0));
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            prefix[i][j] = (mat[i][j] - 'a' + 1);
            if(i > 0 || j > 0) {
                prefix[i][j] += prefix[i - 1][j] + prefix[i][j - 1] - prefix[i - 1][j - 1];
            }
        }
    }

    int count = 0;
    for(int i1 = 0; i1 < n; ++i1) {
        for(int j1 = 0; j1 < m; ++j1) {
            for(int i2 = i1; i2 < n; ++i2) {
                for(int j2 = j1; j2 < m; ++j2) {
                    // Check rows
                    bool is_palin_rows = true;
                    for(int i = i1; i <= i2; ++i) {
                        int sum = prefix[i][j2 + 1] - prefix[i][j1];
                        if(sum % 2 != 0) {
                            is_palin_rows = false;
                            break;
                        }
                        if((j2 - j1 + 1) % 2 == 1) {
                            is_palin_rows = false;
                            break;
                        }
                    }
                    if(!is_palin_rows) continue;

                    // Check columns
                    bool is_palin_cols = true;
                    for(int j = j1; j <= j2; ++j) {
                        int sum = prefix[i2 + 1][j] - prefix[i1][j];
                        if(sum % 2 != 0) {
                            is_palin_cols = false;
                            break;
                        }
                        if((i2 - i1 + 1) % 2 == 1) {
                            is_palin_cols = false;
                            break;
                        }
                    }
                    if(is_palin_cols) {
                        ++count;
                    }
                }
            }
        }
    }

    cout << count << endl;

    return 0;
}
```

### Explanation
1. **Prefix Sum Arrays**: These are used to quickly compute the sum of any submatrix. This helps in efficiently checking the palindrome conditions.
2. **Palindrome Check**: For each submatrix, we check if every row and column can form a palindrome. This involves ensuring that each character's count meets the requirements for a palindrome (even counts for even-length sequences and one odd count for odd-length sequences).
3. **Iterate Over Submatrices**: By iterating over all possible submatrices and checking each one, we count the number of beautiful submatrices that meet the criteria.

This approach ensures that we efficiently check each submatrix while leveraging prefix sums to quickly verify the palindrome conditions.

